import {TYPES,wrapLongitude,longitudeDelta,blastAppearance,operationRanges} from './engine.js';
import {territoryMap} from './territories.js';
import {precisionForZoom,gridZones,mgrsAxisLabels} from './grid.js';
const MUTED='#57727d';
export const SYMBOLS={battleship:'battleship',carrier:'carrier',submarine:'sub',fighter:'fighter',bomber:'bomber',silo:'silo',airbase:'airbase',radar:'radarstation'};
export const unitImage=type=>`<img src="./assets/classic/units/${SYMBOLS[type]}.png" alt="" aria-hidden="true">`;
export class Renderer {
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.zoom=1;this.pan={x:0,y:0};this.selected=null;this.layers={territory:false,seaZones:false,coverage:false,orders:false,population:false,nukes:false};this.gridMode='degree';this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.land=null;this.hover=null;this.width=0;this.height=0;this.elapsed=0;this.territoryFade=0;this.seaFade=0;this.deployTerritory=null;this.textures={};this.tintCache=new Map();this.zones=gridZones();this.axisLabels=[];this.axisKey=null;this.coverage=false;
  for(const name of ['battleship','carrier','sub','sub_surfaced','fighter','bomber','silo','airbase','radarstation','nuke','sam','explosion']){const im=new Image();im.src=`./assets/classic/units/${name}.png`;this.textures[name]=im;}
  this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(canvas);this.ready=fetch('./assets/land.json').then(r=>{if(!r.ok)throw Error('Map unavailable');return r.json();}).then(d=>this.land=d).catch(()=>{this.land=null;});
 }
 get scale(){return Math.max(this.width/360,this.height/180)*this.zoom;}
 get worldWidth(){return 360*this.scale;}
 get zoomPercent(){return (this.zoom-1)/5*100;}
 get precision(){return precisionForZoom(this.zoomPercent);}
 resize(){const focus=this.width&&this.height?this.unproject(this.width/2,this.height/2):{x:0,y:0};const rect=this.canvas.getBoundingClientRect();this.width=rect.width;this.height=rect.height;const ratio=Math.min(devicePixelRatio||1,2);this.canvas.width=rect.width*ratio;this.canvas.height=rect.height*ratio;this.ctx.setTransform(ratio,0,0,ratio,0,0);this.focus(focus.x,focus.y,this.zoom);}
 constrain(){if(!this.scale)return;const world=this.worldWidth;this.pan.x=((this.pan.x+world/2)%world+world)%world-world/2;const vertical=Math.max(0,(180*this.scale-this.height)/2);this.pan.y=Math.max(-vertical,Math.min(vertical,this.pan.y));}
 rawProject(x,y){return {x:this.width/2+x*this.scale+this.pan.x,y:this.height/2-y*this.scale+this.pan.y};}
 project(x,y){const center=this.unproject(this.width/2,this.height/2);return {x:this.width/2+longitudeDelta(center.x,x)*this.scale,y:this.height/2-y*this.scale+this.pan.y};}
 unproject(x,y){return {x:wrapLongitude((x-this.width/2-this.pan.x)/this.scale),y:(this.height/2+this.pan.y-y)/this.scale};}
 copies(x,y,pad=30){const p=this.project(x,y);return [-this.worldWidth,0,this.worldWidth].map(shift=>({x:p.x+shift,y:p.y})).filter(p=>p.x>=-pad&&p.x<=this.width+pad&&p.y>=-pad&&p.y<=this.height+pad);}
 focus(x,y,zoom=this.zoom){this.zoom=Math.max(1,Math.min(6,zoom));this.pan={x:-wrapLongitude(x)*this.scale,y:y*this.scale};this.constrain();}
 reset(lab=false){this.focus(lab?-32.5:0,lab?30:0,lab?2.7:1);}
 changeZoom(factor,x=this.width/2,y=this.height/2){const geo=this.unproject(x,y);this.zoom=Math.max(1,Math.min(6,this.zoom*factor));const p=this.project(geo.x,geo.y);this.pan.x+=x-p.x;this.pan.y+=y-p.y;this.constrain();}
 setZoomPercent(percent){const center=this.unproject(this.width/2,this.height/2);this.focus(center.x,center.y,1+Math.max(0,Math.min(100,percent))/20);}
 setLayer(name,enabled){if(name in this.layers)this.layers[name]=!!enabled;this.coverage=this.layers.coverage;}
 line(x1,y1,x2,y2,color,width=1){const c=this.ctx;c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
 worldLine(a,b,color,width=.7){const start=this.project(a.x,a.y),end={x:start.x+longitudeDelta(a.x,b.x)*this.scale,y:this.project(b.x,b.y).y};for(const shift of [-this.worldWidth,0,this.worldWidth])this.line(start.x+shift,start.y,end.x+shift,end.y,color,width);}
 text(value,x,y,color=MUTED,size=9,align='left'){const c=this.ctx;c.font=`${size}px Consolas,monospace`;c.fillStyle=color;c.textAlign=align;c.fillText(value,x,y);}
 ring(x,y,r,color,width=.7){if(r<=0)return;const c=this.ctx;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
 path(rings,shift=0){const c=this.ctx;c.beginPath();for(const ring of rings){ring.forEach(([x,y],i)=>{const p=this.rawProject(x,y);if(i)c.lineTo(p.x+shift,p.y);else c.moveTo(p.x+shift,p.y);});c.closePath();}}
 drawTerrain(){if(!this.land)return;const c=this.ctx;c.fillStyle='#101f28';c.strokeStyle='#36505c';c.lineWidth=.8;for(const shift of [-this.worldWidth,0,this.worldWidth])for(const f of this.land.features){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;for(const poly of polys){this.path(poly,shift);c.fill('evenodd');c.stroke();}}}
 drawTerritories(sim,dt){const goal=this.layers.territory?1:0;this.territoryFade=this.reduced?goal:Math.max(0,Math.min(1,this.territoryFade+(goal?dt:-dt)*2.5));const seaGoal=this.layers.seaZones?1:0;this.seaFade=this.reduced?seaGoal:Math.max(0,Math.min(1,this.seaFade+(seaGoal?dt:-dt)*2.5));const c=this.ctx;
  for(const f of sim.factions){if(!f.active)continue;const region=territoryMap.regions.find(r=>r.id===f.territory);if(!region)continue;const alpha=this.deployTerritory===f.territory?Math.max(.7,this.territoryFade):this.territoryFade;
   if(this.seaFade>0||this.deployTerritory===f.territory){const opacity=this.deployTerritory===f.territory?1:this.seaFade;c.save();c.globalAlpha=opacity;for(const shift of [-this.worldWidth,0,this.worldWidth]){this.path(region.maritimeRings,shift);c.fillStyle=f.color+'0d';c.fill('evenodd');c.strokeStyle=f.color+'50';c.lineWidth=.8;c.stroke();}c.restore();}
   if(alpha<=0)continue;c.save();c.globalAlpha=alpha;for(const shift of [-this.worldWidth,0,this.worldWidth]){this.path(region.rings,shift);c.fillStyle=f.color+'12';c.fill('evenodd');c.strokeStyle=f.color+'8c';c.lineWidth=1;c.stroke();}c.restore();
  }
 }
 drawGrid(){const c=this.ctx,w=this.width,h=this.height;if(this.gridMode==='mgrs'){
   for(const z of this.zones)for(const shift of [-this.worldWidth,0,this.worldWidth]){const a=this.rawProject(z.west,z.north),b=this.rawProject(z.east,z.south),x=a.x+shift,y=a.y,width=b.x-a.x,height=b.y-a.y;if(x+width<0||x>w||y+height<0||y>h)continue;c.strokeStyle='#28434e60';c.lineWidth=.55;c.strokeRect(x,y,width,height);}
   const key=[w,h,this.pan.x,this.pan.y,this.zoom,this.precision].join('/');if(key!==this.axisKey){this.axisKey=key;this.axisLabels=mgrsAxisLabels({width:w,height:h,unproject:(x,y)=>this.unproject(x,y),precision:this.precision});}
   for(const label of this.axisLabels){const value=`${label.zone} ${label.square} ${label.axis==='x'?'E':'N'}${label.value}`;if(label.axis==='x'){this.line(label.x,label.y-8,label.x,label.y-3,'#587480',.8);this.text(value,label.x,label.y+8,'#78929e',8,'center');}else{this.line(0,label.y,4,label.y,'#587480',.8);this.text(value,8,label.y-5,'#78929e',8);}}
   const topY=w<600?109:82,topLatitude=Math.max(-79.99999,Math.min(83.99999,this.unproject(w/2,topY).y));let last=-100;const row=this.zones.filter(z=>topLatitude>=z.south&&topLatitude<z.north);const markers=[];for(const z of row)for(const shift of [-this.worldWidth,0,this.worldWidth]){const point=this.rawProject((z.west+z.east)/2,0),x=point.x+shift;if(x>24&&x<w-22)markers.push({x,zone:z.zone});}for(const marker of markers.sort((a,b)=>a.x-b.x)){if(marker.x-last<32)continue;this.text(String(marker.zone).padStart(2,'0'),marker.x,topY,'#5d7c88',8,'center');last=marker.x;}
   for(let band=0;band<20;band++){const latitude=band===19?78:-76+band*8,y=this.project(0,latitude).y;if(y<110||y>h-160)continue;this.text('CDEFGHJKLMNPQRSTUVWX'[band],w-9,y,'#5d7c88',8,'right');}
  }else{this.axisLabels=[];const steps=[1,2,5,10,15,30,45,60],step=steps.find(s=>s*this.scale>=90)||60;for(let lon=-180;lon<180;lon+=step)for(const shift of [-this.worldWidth,0,this.worldWidth]){const p=this.rawProject(lon,0),x=p.x+shift;if(x<0||x>w)continue;this.line(x,0,x,h,'#1d354145',.7);this.text(`${Math.abs(lon)}°${lon<0?'W':'E'}`,x+5,h-157,'#4f6975',8);}for(let lat=-90;lat<=90;lat+=step){const p=this.rawProject(0,lat);if(p.y<0||p.y>h)continue;this.line(0,p.y,w,p.y,'#1d354145',.7);this.text(`${Math.abs(lat)}°${lat<0?'S':'N'}`,12,p.y-6,'#4f6975',8);}}
 }
 drawCoverage(sim){if(!this.layers.coverage)return;const c=this.ctx;for(const u of sim.units){if(u.dead||u.landed||TYPES[u.type].radar===0||!(u.team===sim.playerTeam||sim.radarSharing&&sim.allied(u.team,sim.playerTeam)))continue;for(const p of this.copies(u.x,u.y,TYPES[u.type].radar*this.scale)){const radius=TYPES[u.type].radar*this.scale;c.fillStyle=sim.factionColor(u.team)+'07';c.beginPath();c.arc(p.x,p.y,radius,0,7);c.fill();this.ring(p.x,p.y,radius,sim.factionColor(u.team)+'38');}}}
 drawOperations(sim){const u=sim.units.find(u=>u.id===this.selected&&!u.dead&&!u.landed&&sim.visible(u));if(!u)return;const c=this.ctx,colors={weapon:'#d47c71',fuel:'#749bd1',radar:'#7eb9c2',sonar:'#83af9b'},ranges=operationRanges(u);for(const range of ranges){const color=colors[range.kind];if(range.global){c.fillStyle=color+'06';c.fillRect(0,0,this.width,this.height);c.strokeStyle=color+'65';c.lineWidth=.8;c.strokeRect(8,8,this.width-16,this.height-16);continue;}c.save();c.setLineDash(range.kind==='radar'||range.kind==='sonar'?[3,5]:[]);for(const p of this.copies(u.x,u.y,range.radius*this.scale)){this.ring(p.x,p.y,range.radius*this.scale,color+'9c',.9);}c.restore();}for(let i=0;i<ranges.length;i++){const range=ranges[i];this.text(`${range.label}${range.global?'':` / ${range.radius.toFixed(1)}°`}`,20,153+i*16,colors[range.kind],9);}}

 drawCities(sim){const c=this.ctx;for(const city of sim.cities){const color=sim.factionColor(city.team);for(const p of this.copies(city.x,city.y,80)){const size=Math.max(1.2,Math.sqrt(city.pop)*1.2);if(this.layers.population&&city.pop>.1){const radius=Math.max(7,Math.sqrt(city.pop)*5),g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,radius);g.addColorStop(0,color+'34');g.addColorStop(1,color+'00');c.fillStyle=g;c.fillRect(p.x-radius,p.y-radius,radius*2,radius*2);}c.save();c.globalAlpha=city.dead?.2:.65;c.translate(p.x,p.y);c.rotate(Math.PI/4);c.fillStyle=color;c.fillRect(-size/2,-size/2,size,size);c.restore();if(this.layers.population||city.pop>9||this.zoom>3.5){this.text(city.name.toUpperCase(),p.x+6,p.y-4,color+'bb',8);if(this.layers.population)this.text(`${city.pop.toFixed(2)}M`,p.x+6,p.y+8,'#82959f',8);}}}}
 drawUnit(sim,u,p,ghost=false){const c=this.ctx,t=TYPES[u.type],color=sim.factionColor(u.team),selected=this.selected===u.id;c.globalAlpha=ghost?.18:selected?1:.52;if(selected&&!ghost){this.ring(p.x,p.y,14,color+'b0');this.line(p.x-20,p.y,p.x-16,p.y,color);this.line(p.x+16,p.y,p.x+20,p.y,color);}
  this.unitIcon(u,p.x,p.y,color);c.globalAlpha=1;if(selected&&!ghost){this.text(`${u.type.toUpperCase()} ${u.id}`,p.x+12,p.y-10,color,8);c.fillStyle='#263640';c.fillRect(p.x-9,p.y+13,18,2);c.fillStyle=color;c.fillRect(p.x-9,p.y+13,18*u.hp/u.maxHp,2);}if(!ghost&&this.layers.nukes&&sim.allied(u.team,sim.playerTeam)&&(u.ammo+u.stockNukes)>0)this.text(`☢ ${u.ammo+u.stockNukes}`,p.x+10,p.y+12,color,9);
 }
 drawUnits(sim){if(sim.mode==='war'&&!sim.started)return;const c=this.ctx;for(const u of sim.units){if(u.dead||u.landed||!sim.visible(u))continue;const color=sim.factionColor(u.team);for(let i=1;i<u.trail.length;i++)this.worldLine(u.trail[i-1],u.trail[i],color+'2c',.7);if(u.order&&(this.selected===u.id||this.layers.orders&&u.team===sim.playerTeam&&(!u.fleetId||sim.fleets.find(f=>f.id===u.fleetId)?.members[0]===u.id))){c.setLineDash([3,5]);this.worldLine(u,u.order,color+'7a');c.setLineDash([]);}for(const p of this.copies(u.x,u.y))this.drawUnit(sim,u,p);}
  for(const ghost of sim.ghosts.values()){const unit=sim.units.find(u=>u.id===ghost.id);if(unit&&!unit.dead&&sim.visible(unit))continue;if(unit&&TYPES[unit.type].speed&&Math.hypot(longitudeDelta(unit.x,ghost.x),unit.y-ghost.y)>.5)continue;for(const p of this.copies(ghost.x,ghost.y))this.drawUnit(sim,ghost,p,true);}
 }
 drawMissiles(sim){const c=this.ctx;for(const m of sim.missiles){const start=this.project(m.sx,m.sy),target=this.project(m.tx,m.ty),dx=longitudeDelta(m.sx,m.tx),distance=Math.hypot(dx,m.ty-m.sy),rise=Math.min(35,distance*.35);for(const shift of [-this.worldWidth,0,this.worldWidth]){c.beginPath();c.moveTo(start.x+shift,start.y);c.quadraticCurveTo(start.x+dx*this.scale/2+shift,(start.y+target.y)/2-rise*2*this.scale,start.x+dx*this.scale+shift,target.y);c.strokeStyle=sim.factionColor(m.team)+'40';c.lineWidth=.8;c.stroke();}for(const p of this.copies(m.x,m.y)){const heading=Math.atan2(m.ty-m.sy+Math.cos(m.p*Math.PI)*rise*Math.PI,dx);c.globalAlpha=.8;this.unitIcon({type:'nuke',heading},p.x,p.y,sim.factionColor(m.team),.85);c.globalAlpha=1;}}
  for(const shot of sim.shots){const color=sim.factionColor(shot.team);for(let i=1;i<shot.trail.length;i++)this.worldLine(shot.trail[i-1],shot.trail[i],color+'75',1);for(const p of this.copies(shot.x,shot.y)){c.save();c.globalAlpha=.85;if(shot.kind==='sam')this.unitIcon({type:'sam',heading:shot.heading},p.x,p.y,color,.46);else{c.translate(p.x,p.y);c.rotate(-shot.heading);c.fillStyle=color;c.fillRect(-3,-.7,6,1.4);}c.restore();}}
 }
 drawExplosions(sim){const c=this.ctx;for(const blast of sim.blasts){const {alpha,radius:worldRadius}=blastAppearance(blast);if(!alpha)continue;const radius=Math.max(.5,worldRadius*this.scale);for(const p of this.copies(blast.x,blast.y,radius)){c.save();c.globalAlpha=alpha*(blast.miss?.35:1);c.globalCompositeOperation='lighter';const g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,radius);g.addColorStop(0,blast.nuclear?'#fff4d6ad':'#ffd4ac90');g.addColorStop(.16,'#f9d4ab85');g.addColorStop(.6,'#dba87828');g.addColorStop(1,'#df704000');c.fillStyle=g;c.fillRect(p.x-radius,p.y-radius,radius*2,radius*2);if(blast.nuclear){const ring=c.createRadialGradient(p.x,p.y,radius*.52,p.x,p.y,radius);ring.addColorStop(0,'#fff4dc00');ring.addColorStop(.5,'#f4dfc126');ring.addColorStop(.72,'#fff0d554');ring.addColorStop(1,'#dfc39e00');c.fillStyle=ring;c.fillRect(p.x-radius,p.y-radius,radius*2,radius*2);}c.restore();}}}

 draw(sim,dt){if(!this.width||!this.height)return;this.constrain();this.elapsed+=dt;const c=this.ctx;c.clearRect(0,0,this.width,this.height);c.fillStyle='#080f14';c.fillRect(0,0,this.width,this.height);this.drawTerrain();this.drawTerritories(sim,dt);this.drawGrid();this.drawCoverage(sim);this.drawCities(sim);this.drawOperations(sim);this.drawUnits(sim);this.drawMissiles(sim);this.drawExplosions(sim);if(this.hover){for(const p of this.copies(this.hover.x,this.hover.y)){this.line(p.x-7,p.y,p.x-3,p.y,'#8ba8b455',.6);this.line(p.x+3,p.y,p.x+7,p.y,'#8ba8b455',.6);}}}
 unitIcon(u,x,y,color,scale=1){const c=this.ctx,name=u.type==='submarine'&&u.mode==='launch'?'sub_surfaced':TYPES[u.type]?.icon||(u.type==='nuke'?'nuke':u.type==='sam'?'sam':null),image=this.textures[name];if(!image?.complete||!image.naturalWidth)return;const key=name+color;let tint=this.tintCache.get(key);if(!tint){tint=document.createElement('canvas');tint.width=image.naturalWidth;tint.height=image.naturalHeight;const tc=tint.getContext('2d');tc.drawImage(image,0,0);tc.globalCompositeOperation='source-in';tc.fillStyle=color;tc.fillRect(0,0,tint.width,tint.height);this.tintCache.set(key,tint);}const size=Math.max(11,Math.min(25,12*Math.sqrt(this.zoom)))*scale;c.save();c.translate(x,y);if(TYPES[u.type]?.domain==='air'||u.type==='nuke'||u.type==='sam')c.rotate(Math.PI/2-u.heading);c.drawImage(tint,-size/2,-size/2,size,size);c.restore();}
 pick(sim,x,y){if(sim.mode==='war'&&!sim.started)return null;let best=null,minimum=16;for(const u of sim.units){if(u.dead||u.landed||!sim.visible(u))continue;for(const p of this.copies(u.x,u.y)){const d=Math.hypot(p.x-x,p.y-y);if(d<minimum){best=u;minimum=d;}}}return best;}
}
